	onSelect: (modelId: string) => void;
}

/**
 * Image generation uses a different API contract from chat. This contextual
 * picker deliberately receives only the selected generator's image models, so
 * a chat model can never be chosen for an image-generation retry or setting.
 */
export function ImageGenerationModelSelectorDialog({
	open,
	generator,
	currentModelId,
	onClose,
	onSelect,
}: ImageGenerationModelSelectorDialogProps) {
	const defaultModel = currentModelId || generator.models[0] || "";
	const [selectedModel, setSelectedModel] = useState(defaultModel);
	const [search, setSearch] = useState("");
	const inputRef = useRef<HTMLInputElement>(null);

	useEffect(() => {
		if (!open) return;
		setSelectedModel(currentModelId || generator.models[0] || "");
		setSearch("");
		window.setTimeout(() => inputRef.current?.focus(), 50);
	}, [open, currentModelId, generator]);

	if (!open) return null;

	const query = search.trim().toLowerCase();
	const models = generator.models.filter((model) => !query || model.toLowerCase().includes(query));

