	const [open, setOpen] = useState(initialOpen);

	const onOpen = useCallback(() => {
		setOpen(true);
	}, []);

	const onClose = useCallback(() => {
		setOpen(false);
	}, []);

	const toggle = useCallback(() => {
		setOpen((prev) => !prev);
	}, []);

	return { open, onOpen, onClose, toggle };
}
